using System;
using System.Collections.Generic;
using System.Globalization;
using System.Text;

namespace TaskbarNet {
internal static class Ui {
    static volatile string language=Resolve("auto",CultureInfo.CurrentUICulture);
    public static string Language {get{return language;}}
    public static string Resolve(string choice,CultureInfo system){return choice=="ru"||choice=="en"?choice:system.TwoLetterISOLanguageName=="ru"?"ru":"en";}
    public static void SetLanguage(string choice){language=Resolve(choice,CultureInfo.CurrentUICulture);}
    public static string T(string russian){string english;return language=="en"&&English.TryGetValue(russian,out english)?english:russian;}
    public static string Help(string key){string[] value=Hints[key];return Wrap(value[language=="en"?1:0]);}
    public static string Seconds(int value){return value==0?T("Выключено"):value+T(" с");}
    public static string Wrap(string value){
        var result=new StringBuilder();foreach(string paragraph in value.Replace("\r","").Split('\n')){
            if(result.Length>0)result.Append('\n');int width=0;
            foreach(string word in paragraph.Split(new[]{' '},StringSplitOptions.RemoveEmptyEntries)){if(width>0){if(width+word.Length+1>64){result.Append('\n');width=0;}else{result.Append(' ');width++;}}result.Append(word);width+=word.Length;}
        }return result.ToString();
    }
