    static readonly Dictionary<string,string[]> Hints=new Dictionary<string,string[]>{
        {"iconChoice",new[]{"Выберите «Потоки» (вариант 1), «Спидометр» (вариант 3) или добавленную иконку. Меняет значок в трее и окнах приложения после «Применить». Выбор сохраняется. Если свой файл недоступен, используется «Потоки».","Choose Flows (option 1), Speedometer (option 3) or an imported icon. Apply changes the tray and app-window icons and saves your selection. If a custom file is unavailable, Flows is used."}},
        {"iconImport",new[]{"Добавить один или несколько ICO или PNG до 10 МБ. PNG преобразуется в значок нескольких размеров с сохранением пропорций и прозрачности. Копии хранятся только в папке TaskbarNet; затем выберите значок и нажмите «Применить».","Add one or more ICO or PNG files up to 10 MB. PNG files become multi-size icons with aspect ratio and transparency preserved. Copies are kept in TaskbarNet's folder. Select an icon and choose Apply."}},
        {"iconPreview",new[]{"Предпросмотр выбранной иконки в размерах 16, 24, 32 и 64 при масштабе Windows 100%. Масштабируется вместе с интерфейсом. До «Применить» значок приложения сохраняется прежним.","Preview of the selected icon at 16, 24, 32 and 64 pixels at 100% Windows scaling. Scales with the interface. The active app icon changes when you choose Apply."}},
        {"tabIcons",new[]{"Выбор двух встроенных иконок или добавление своих файлов ICO и PNG.","Choose either built-in icon or add your own ICO and PNG files."}},
        {"language",new[]{"Язык меню, настроек, сообщений и подсказок. Автоматически — русский для русского языка интерфейса Windows, английский для остальных. Выбор сохраняется; ручной выбор не зависит от языка Windows.","Language of menus, settings, messages and tooltips. Automatic uses Russian for a Russian Windows display language and English otherwise. Your manual choice is saved independently of Windows."}},
        {"adapter",new[]{"Считает трафик только выбранного интерфейса. Автоматический выбор следует системному маршруту в интернет. VPN и физический интерфейс не складываются; смена адаптера очищает прежнюю историю.","Measures only the selected interface. Automatic follows the system internet route. VPN and physical-interface traffic are not added together. Changing the adapter clears the old history."}},
        {"adapterAuto",new[]{"Выбрать один интерфейс по системному маршруту в интернет. При VPN это может быть виртуальный адаптер.","Select one interface using the system internet route. With a VPN this may be a virtual adapter."}},
        {"adapterManual",new[]{"Считать скорость только этого адаптера. Полезно, если автоматический маршрут выбирает другой интерфейс. Отключённый адаптер показывает прочерки.","Measure only this adapter. Useful when Automatic chooses a different interface. A disconnected adapter shows dashes."}},
        {"units",new[]{"Меняет единицы чисел и подсказки в трее. Байты — kB/s и MB/s; биты — kbit/s и Mbit/s, в 8 раз больше. Десятичные единицы: 1000 байт = 1 kB. Шкала графика в MB/s задаётся отдельно.","Changes units in the numbers and tray tooltip. Bytes use kB/s and MB/s; bits use kbit/s and Mbit/s, with values 8 times larger. Decimal units: 1000 bytes = 1 kB. The fixed graph limit is always in MB/s."}},
        {"fontSize",new[]{"Размер чисел и стрелок, 6–24 пункта. Больше — крупнее текст; высота ограничена панелью задач. Автоматическая ширина подстраивается под размер. Размер меню и настроек остаётся удобным для интерфейса.","Size of the numbers and arrows, 6–24 points. Higher values enlarge the text up to the taskbar height limit. Automatic width adapts to the size. Menus and settings keep their own UI text size."}},
        {"interval",new[]{"Как часто меняются числа: 0,5, 1 или 2 секунды. Меньше — быстрее видна смена скорости; больше — спокойнее показания. Частота анимации графика регулируется отдельно.","How often numbers change: 0.5, 1 or 2 seconds. Lower values show changes sooner; higher values keep the display steadier. Graph animation has a separate frame rate."}},
        {"smoothing",new[]{"Усреднение только чисел за 2–10 секунд. Больше — слабее короткие пики и медленнее реакция. Выключено — скорость за последний интервал обновления. Плавность графика настраивается отдельно.","Averages only the numbers over 2–10 seconds. Higher values soften short spikes and delay the response. Off shows the last numeric sampling interval. Graph smoothing is independent."}},
        {"panelWidth",new[]{"Ширина в логических пикселях при масштабе Windows 100%. Больше — дальше стрелки слева от чисел справа; размер текста не меняется. Минимум зависит от шрифта, максимум ограничен свободным местом панели задач.","Width in logical pixels at 100% Windows scaling. A larger width increases the gap between left-hand arrows and right-aligned numbers without changing text size. The font and available taskbar space limit the width."}},
        {"autoWidth",new[]{"Подбирать ширину по шрифту и размеру текста. Выключите, чтобы задать её числом; перетаскивание левого края также сохраняет ручную ширину.","Size the panel to its font and text size. Turn off to enter a width. Dragging the left edge also saves a manual width."}},
        {"startup",new[]{"Запускать TaskbarNet при входе в вашу учётную запись Windows. Индикатор появится автоматически. Права администратора не нужны.","Start TaskbarNet when you sign in to your Windows account so the indicator appears automatically. No administrator rights are needed."}},
        {"graphEnabled",new[]{"Показывать две линии скорости позади текста. При выключении сохраняются параметры оформления и отключаются частые замеры и анимация графика.","Show two speed lines behind the text. Turning this off keeps graph preferences and stops fast graph sampling and animation."}},
        {"graphFps",new[]{"Целевая частота движения графика, 5–30 кадров/с. Больше — плавнее прокрутка и больше перерисовок. Реальные замеры графика выполняются 5 раз/с; числа обновляются по своему интервалу.","Target graph frame rate, 5–30 fps. Higher values make scrolling smoother and require more redraws. Real graph samples arrive 5 times/s; numbers use their own refresh interval."}},
        {"graphSmoothing",new[]{"Сглаживание только графика: 0–5 секунд, шаг 0,1. Больше — плавнее пики и медленнее реакция. 0 показывает исходные замеры. После применения вся видимая история пересчитывается сразу; усреднение чисел сохраняется.","Graph-only smoothing: 0–5 seconds in 0.1 steps. Higher values soften spikes and slow the response. Zero shows raw samples. Apply recalculates the visible history immediately while keeping numeric averaging unchanged."}},
        {"graphSeconds",new[]{"Сколько секунд помещается по ширине графика: 15–120. Больше — длиннее история, отдельные всплески уже; меньше — лучше видны быстрые изменения.","Seconds visible across the graph: 15–120. A larger value shows more history with narrower spikes; a smaller value reveals rapid changes more clearly."}},
        {"graphOpacity",new[]{"Непрозрачность линий, 5–60%. Больше — график заметнее; меньше — фон спокойнее и текст легче читать. Первые и последние 10% графика плавно затухают.","Line opacity, 5–60%. Higher values make the graph more visible; lower values keep the background subtle and text easier to read. The first and last 10% fade out smoothly."}},
        {"graphLineWidth",new[]{"Толщина линий графика, 0,5–3 логических пикселя. Больше — жирнее контур; размер чисел и стрелок сохраняется.","Graph line width, 0.5–3 logical pixels. Higher values make the outline thicker while keeping the numbers and arrows the same size."}},
        {"graphScale",new[]{"Общая вертикальная шкала для загрузки и отдачи. Автоматическая подстраивается под видимые пики. Фиксированная сохраняет одинаковый масштаб; её предел задаётся ниже.","Shared vertical scale for download and upload. Automatic follows visible peaks. Fixed keeps the same scale over time, using the limit below."}},
        {"graphMaximum",new[]{"Верхняя граница фиксированной шкалы в MB/s, даже если числа показаны в битах. Больше — пики ниже; меньше — выше. Значения выше предела обрезаются по верхнему краю. Поле работает при фиксированной шкале.","Upper limit of the fixed graph scale in MB/s, even when numbers use bits. A higher limit makes peaks shorter; a lower limit makes them taller. Values above the limit are clipped. Available in Fixed scale mode."}},
        {"downColor",new[]{"Цвет линии загрузки ↓ и её заливки. Выберите цвет, который заметен на вашей панели задач и отличается от отдачи.","Color of the download ↓ line and its fill. Choose a color visible against your taskbar and distinct from upload."}},
        {"upColor",new[]{"Цвет линии отдачи ↑ и её заливки. Отдельный цвет помогает отличать отправку данных от загрузки.","Color of the upload ↑ line and its fill. A distinct color helps separate sent and received traffic."}},
        {"graphFill",new[]{"Добавить слабую полупрозрачную заливку под обеими линиями. Выключите для минималистичного графика только из контуров.","Add a faint translucent fill below both lines. Turn off for a minimal graph with outlines only."}},
        {"fontFamily",new[]{"Шрифт чисел и стрелок. Выберите установленное семейство или добавьте свой файл. Длинное имя полностью видно в раскрытом списке. Предпросмотр показывает выбранное начертание и размер.","Font for numbers and arrows. Choose an installed family or add your own file. The dropdown shows long names in full. The preview uses the chosen style and size."}},
        {"fontStyle",new[]{"Обычный, полужирный, курсив или полужирный курсив. Меняет начертание текста индикатора. Если шрифт не содержит выбранного начертания, используется доступное.","Regular, bold, italic or bold italic. Changes indicator text style. If the font lacks that style, an available style is used."}},
        {"fontForUi",new[]{"Применять выбранное семейство и начертание также к меню и настройкам. При выключении интерфейс использует Segoe UI. Размер чисел задаётся отдельно на вкладке «Основное».","Also use the chosen family and style in menus and settings. When off, the interface uses Segoe UI. Number size is set separately on General."}},
        {"fontImport",new[]{"Добавить TTF, TTC или совместимый OTF до 50 МБ. Файлы копируются в папку TaskbarNet и доступны только приложению. После импорта выберите шрифт и нажмите «Применить».","Add a TTF, TTC or compatible OTF up to 50 MB. Files are copied to TaskbarNet's folder and are private to this app. Select the imported font and choose Apply."}},
        {"fontReset",new[]{"Выбрать Segoe UI, обычное начертание и стандартный шрифт интерфейса. Для сохранения нажмите «Применить». Размер чисел сохраняется.","Choose Segoe UI, regular style and the default interface font. Choose Apply to save. Number size is kept."}},
        {"fontPreview",new[]{"Образец шрифта, начертания и размера. Основной индикатор применит выбор после «Применить», с учётом доступной высоты панели задач.","Preview of the font, style and size. Apply updates the indicator, whose text is also limited by the available taskbar height."}},
        {"apply",new[]{"Сохранить параметры всех вкладок и сразу обновить индикатор. Новый язык применяется без перезапуска; сглаживание пересчитывает всю видимую историю графика.","Save all tabs and update the indicator immediately. Language changes need no restart; smoothing recalculates the visible graph history."}},
        {"close",new[]{"Закрыть настройки. Не применённые изменения не сохраняются; индикатор продолжает работать в панели задач.","Close settings. Unapplied changes are not saved; the taskbar indicator keeps running."}},
        {"resize",new[]{"Включить изменение ширины перетаскиванием левого края индикатора. Правый край и размер текста сохраняются. Большая ширина увеличивает промежуток между стрелками и числами. Выключите после настройки, чтобы не изменить ширину случайно.","Enable dragging the indicator's left edge to resize it. The right edge and text size stay fixed. A wider panel increases the gap between arrows and numbers. Turn off afterwards to avoid accidental resizing."}},
        {"resetWidth",new[]{"Вернуть автоматическую ширину по текущему шрифту и размеру текста вместо ширины, выбранной перетаскиванием.","Restore automatic width based on the current font and text size, replacing the width set by dragging."}},
        {"settings",new[]{"Открыть параметры чисел, графика, шрифтов и языка. Чтобы узнать действие параметра, наведите на его название или поле.","Open settings for numbers, graph, fonts and language. Hover over a setting label or field to learn what it changes."}},
        {"exit",new[]{"Завершить TaskbarNet и убрать индикатор с панели задач. Сохранённые настройки и включённый автозапуск остаются.","Exit TaskbarNet and remove its taskbar indicator. Saved preferences and enabled startup remain."}},
        {"version",new[]{"TaskbarNet — текущая скорость загрузки и отдачи внутри стандартной панели задач Windows 11.","TaskbarNet shows current download and upload speed inside the standard Windows 11 taskbar."}},
        {"status",new[]{"Текущий сетевой адаптер или состояние соединения. Скорость отражает трафик интерфейса, включая локальную сеть, а не максимальную скорость тарифа.","Current network adapter or connection status. Speed reflects interface traffic, including LAN traffic, rather than your plan's maximum speed."}},
        {"tabMain",new[]{"Адаптер, единицы, размер и усреднение чисел, язык и автозапуск.","Adapter, units, number size and averaging, language and startup."}},
        {"tabGraph",new[]{"Частота, плавность, история и внешний вид графика. Его сглаживание независимо от усреднения чисел.","Graph frame rate, smoothing, history and appearance. Graph smoothing is independent of numeric averaging."}},
        {"tabFonts",new[]{"Выбор семейства и начертания, предпросмотр и импорт своих шрифтов.","Font family and style, preview and custom font imports."}}
    };
